urlset:
{% for page in pages %}

        {{ canonical_host }}{{ page.path }}
        {{ page.changefreq }}
        {{ page.priority }}
        {% if page.photos %}
            {% for photo in page.photos %}

                {{ canonical_host }}/media/photo/{{ photo.filename }}
                {{ photo.title }}
                {{ photo.caption|default(photo.title) }}

            {% endfor %}
        {% endif %}

{% endfor %}
